import networkx as nx

from dowhy.causal_identifier.adjustment_set import AdjustmentSet
from dowhy.causal_identifier.backdoor import Backdoor, HittingSetAlgorithm, NodePair, Path


class TestPath:
    def test_initial_state_is_unknown_and_unconditional(self):
        path = Path()

        assert path.is_blocked() is None
        assert path.get_condition_vars() == set()

    def test_update_with_unblocked_path_records_intermediate_nodes(self):
        path = Path()

        path.update(["X", "A", "B", "Y"], is_blocked=False)

        assert path.is_blocked() is False
        assert path.get_condition_vars() == {"A", "B"}

    def test_update_with_blocked_path_keeps_condition_vars_empty(self):
        path = Path()

        path.update(["X", "A", "Y"], is_blocked=True)

        assert path.is_blocked() is True
        assert path.get_condition_vars() == set()

    def test_repeated_unblocked_updates_union_condition_vars(self):
        path = Path()

        path.update(["X", "A", "Y"], is_blocked=False)
        path.update(["X", "B", "Y"], is_blocked=False)

        assert path.get_condition_vars() == {"A", "B"}

    def test_str_mentions_blocking_variables(self):
        path = Path()
        path.update(["X", "A", "Y"], is_blocked=False)

        rendered = str(path)

        assert "Blocked: False" in rendered
        assert "A" in rendered

    def test_str_of_blocked_path_has_no_condition_suggestion(self):
        path = Path()
        path.update(["X", "A", "Y"], is_blocked=True)

        assert str(path) == "Blocked: True\n"


class TestNodePair:
    def test_initial_state(self):
        node_pair = NodePair("X", "Y")

        assert node_pair.get_condition_vars() == []
        assert node_pair.is_complete() is False

    def test_update_from_path_accumulates_path_condition_vars(self):
        node_pair = NodePair("X", "Y")
        path = Path()
        path.update(["X", "A", "B"], is_blocked=False)

        node_pair.update(path)

        assert node_pair.get_condition_vars() == [{"A", "B"}]

    def test_update_from_list_combines_path_and_extra_condition_vars(self):
        node_pair = NodePair("X", "Y")

        node_pair.update(["X", "A", "B"], {"C"})

        assert node_pair.get_condition_vars() == [{"A", "B", "C"}]

    def test_completeness_flag(self):
        node_pair = NodePair("X", "Y")

        node_pair.set_complete()

        assert node_pair.is_complete() is True

    def test_str_mentions_blocking_variables_for_unblocked_path(self):
        node_pair = NodePair("X", "Y")
        node_pair.update(["X", "A", "B"], {"C"})

        rendered = str(node_pair)

        assert "Blocked: False" in rendered
        assert "A" in rendered


class TestHittingSetAlgorithm:
    def test_num_sets_returns_number_of_backdoor_paths(self):
        algorithm = HittingSetAlgorithm([{"A"}, {"B"}, {"C"}])

        assert algorithm.num_sets() == 3

    def test_find_set_returns_var_hitting_every_set(self):
        # B appears in all three sets and is therefore the unique best choice.
        algorithm = HittingSetAlgorithm([{"A", "B"}, {"B", "C"}, {"B", "D"}])

        hitting_set = algorithm.find_set()

        assert hitting_set == {"B"}
        assert all(hitting_set.intersection(s) for s in [{"A", "B"}, {"B", "C"}, {"B", "D"}])

    def test_find_set_ignores_colliders(self):
        algorithm = HittingSetAlgorithm([{"A"}, {"B"}], colliders={"A"})

        assert algorithm.find_set() == {"B"}

    def test_find_set_on_empty_collection_is_empty(self):
        algorithm = HittingSetAlgorithm([])

        assert algorithm.num_sets() == 0
        assert algorithm.find_set() == set()


class TestBackdoor:
    def test_simple_confounder_yields_backdoor_set(self):
        graph = nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])

        backdoor_sets = Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars()

        assert len(backdoor_sets) == 1
        adjustment_set = backdoor_sets[0]
        assert adjustment_set.get_adjustment_type() == AdjustmentSet.BACKDOOR
        assert set(adjustment_set.get_adjustment_variables()) == {"Z"}
        assert adjustment_set.get_num_paths_blocked_by_observed_nodes() == 1

    def test_no_backdoor_paths_yields_no_adjustment_sets(self):
        graph = nx.DiGraph([("X", "Y")])

        assert Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars() == []

    def test_collider_paths_are_not_treated_as_backdoor_paths(self):
        # X -> C <- Y is a collider path, not a confounding path.
        graph = nx.DiGraph([("X", "Y"), ("X", "C"), ("Y", "C")])

        assert Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars() == []

    def test_chain_confounder_is_blocked_by_ancestor(self):
        graph = nx.DiGraph([("B", "A"), ("A", "X"), ("B", "Y"), ("X", "Y")])

        backdoor_sets = Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars()

        assert len(backdoor_sets) == 1
        assert set(backdoor_sets[0].get_adjustment_variables()) == {"B"}

    def test_two_independent_confounders_are_both_selected(self):
        graph = nx.DiGraph(
            [("A", "X"), ("A", "Y"), ("B", "X"), ("B", "Y"), ("X", "Y")]
        )

        backdoor_sets = Backdoor(graph, ["X"], ["Y"]).get_backdoor_vars()

        assert len(backdoor_sets) == 1
        assert set(backdoor_sets[0].get_adjustment_variables()) == {"A", "B"}

    def test_is_backdoor_detects_incoming_edge_from_first_path_node(self):
        graph = nx.DiGraph([("Z", "X"), ("X", "Y")])
        backdoor = Backdoor(graph, ["X"], ["Y"])

        assert backdoor.is_backdoor(["X", "Z", "Y"]) is True
        assert backdoor.is_backdoor(["Y", "Z", "X"]) is False
        assert backdoor.is_backdoor(["X"]) is False
