import networkx as nx
import pytest

from dowhy.causal_identifier.efficient_backdoor import (
    EXCEPTION_COND_NO_OPT,
    EXCEPTION_NO_ADJ,
    EfficientBackdoor,
)
from dowhy.graph import check_valid_backdoor_set


def simple_confounded_graph():
    return nx.DiGraph([("Z", "X"), ("Z", "Y"), ("X", "Y")])


def diamond_graph():
    # Two alternative ways of blocking the confounding: {A, B} or the cheaper {C}.
    return nx.DiGraph(
        [("A", "X"), ("B", "X"), ("A", "C"), ("B", "C"), ("C", "Y"), ("X", "Y")]
    )


class TestConstructionValidation:
    def test_rejects_multidimensional_treatment(self):
        graph = simple_confounded_graph()

        with pytest.raises(ValueError, match="one dimensional treatments"):
            EfficientBackdoor(graph, ["X", "Z"], ["Y"], ["X", "Y", "Z"])

    def test_rejects_multidimensional_outcome(self):
        graph = simple_confounded_graph()

        with pytest.raises(ValueError, match="one dimensional outcomes"):
            EfficientBackdoor(graph, ["X"], ["Y", "Z"], ["X", "Y", "Z"])

    def test_rejects_non_positive_costs(self):
        graph = simple_confounded_graph()

        with pytest.raises(ValueError, match="All costs must be positive"):
            EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y", "Z"], costs=[("X", {"cost": 0})])

    def test_rejects_unobserved_conditional_variables(self):
        graph = simple_confounded_graph()

        with pytest.raises(ValueError, match="not marked as observed"):
            EfficientBackdoor(
                graph, ["X"], ["Y"], ["X", "Y"], conditional_node_names=["Z"]
            )


class TestGraphHelpers:
    def test_ancestors_all_includes_the_nodes_themselves(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.ancestors_all(["X"]) == {"Z", "X"}

    def test_backdoor_graph_removes_treatment_to_outcome_edge(self):
        graph = simple_confounded_graph()
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y", "Z"])

        backdoor_graph = efficient.backdoor_graph(graph)

        assert ("X", "Y") not in backdoor_graph.edges
        assert set(backdoor_graph.edges) == {("Z", "X"), ("Z", "Y")}
        # The original graph is not modified.
        assert ("X", "Y") in graph.edges

    def test_causal_vertices_exclude_treatment(self):
        graph = nx.DiGraph([("X", "M"), ("M", "Y"), ("Z", "X")])
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], ["X", "M", "Y", "Z"])

        assert efficient.causal_vertices() == {"M", "Y"}

    def test_forbidden_set(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.forbidden() == {"X", "Y"}

    def test_ignore_is_empty_when_all_relevant_variables_are_observed(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.ignore() == set()

    def test_build_h0_and_h1_for_simple_confounder(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        h0 = efficient.build_H0()
        h1 = efficient.build_H1()

        assert set(h0.nodes) == {"Z", "X", "Y"}
        assert set(h1.nodes) == {"Z", "X", "Y"}
        assert {frozenset(edge) for edge in h1.edges} == {
            frozenset(("Z", "X")),
            frozenset(("Z", "Y")),
        }

    def test_build_d_contains_primal_and_capacity_edges(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        flow_network = efficient.build_D()

        assert flow_network.has_edge("Z'", "Z''")
        assert flow_network["Z'"]["Z''"]["capacity"] == 1
        assert flow_network.has_edge("Z''", "X'")
        assert flow_network.has_edge("X''", "Z'")


class TestAdjustmentSets:
    def test_optimal_adjustment_set_for_simple_confounder(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.optimal_adj_set() == {"Z"}

    def test_optimal_minimal_adjustment_set_for_simple_confounder(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.optimal_minimal_adj_set() == {"Z"}

    def test_optimal_mincost_adjustment_set_for_simple_confounder(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.optimal_mincost_adj_set() == {"Z"}

    def test_all_optimal_variants_pick_the_single_blocking_node(self):
        graph = diamond_graph()
        observed = ["X", "Y", "A", "B", "C"]
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], observed)

        for method_name in (
            "optimal_adj_set",
            "optimal_minimal_adj_set",
            "optimal_mincost_adj_set",
        ):
            adjustment_set = getattr(efficient, method_name)()
            check = check_valid_backdoor_set(
                graph, ["X"], ["Y"], adjustment_set, dseparation_algo="default"
            )
            assert adjustment_set == {"C"}
            assert check["is_dseparated"] is True

    def test_mincost_uses_costs_when_choosing_between_sets(self):
        graph = diamond_graph()
        observed = ["X", "Y", "A", "B", "C"]
        costs = [("C", {"cost": 1}), ("A", {"cost": 5}), ("B", {"cost": 5})]
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], observed, costs=costs)

        assert efficient.optimal_mincost_adj_set() == {"C"}

    def test_empty_set_is_returned_when_no_confounding_exists(self):
        graph = nx.DiGraph([("X", "Y")])
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y"])

        assert efficient.optimal_adj_set() == set()
        assert efficient.optimal_minimal_adj_set() == set()
        assert efficient.optimal_mincost_adj_set() == set()

    @pytest.mark.parametrize(
        "method_name",
        ["optimal_adj_set", "optimal_minimal_adj_set", "optimal_mincost_adj_set"],
    )
    def test_latent_confounding_raises_no_adjustment_error(self, method_name):
        graph = nx.DiGraph([("U", "X"), ("U", "Y"), ("X", "Y")])
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y"])

        with pytest.raises(ValueError) as excinfo:
            getattr(efficient, method_name)()

        assert excinfo.value.args[0] == EXCEPTION_NO_ADJ

    def test_optimal_adj_set_rejects_conditions_for_optimality(self):
        graph = nx.DiGraph([("U", "Y"), ("Z", "X"), ("Z", "Y"), ("X", "Y")])
        graph.add_node("W")
        efficient = EfficientBackdoor(graph, ["X"], ["Y"], ["X", "Y", "Z", "W"])

        with pytest.raises(ValueError) as excinfo:
            efficient.optimal_adj_set()

        assert excinfo.value.args[0] == EXCEPTION_COND_NO_OPT


class TestMincutHelpers:
    def test_smallest_mincut_operator_yields_backdoor_set(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        smallest_mincut = efficient.compute_smallest_mincut()

        assert "Y''" in smallest_mincut
        assert efficient.h_operator(smallest_mincut) == {"Z"}

    def test_h_operator_selects_nodes_with_only_primal_vertex_in_cut(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])

        assert efficient.h_operator({"Z'", "Y''"}) == {"Z"}
        assert efficient.h_operator({"Z''"}) == set()

    def test_unblocked_returns_boundary_of_treatment_component(self):
        efficient = EfficientBackdoor(simple_confounded_graph(), ["X"], ["Y"], ["X", "Y", "Z"])
        h1 = efficient.build_H1()

        unblocked = efficient.unblocked(h1, {"Z"})

        assert unblocked == {"Z"}
